type Fn = () => void;
const registered: [string, Fn][] = [];
const cleanups: (() => void)[] = [];

export function test(name: string, fn: Fn): void {
  registered.push([name, fn]);
}

export function onCleanup(fn: () => void): void {
  cleanups.push(fn);
}

export function eq(actual: unknown, expected: unknown, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
}

export function assert(cond: boolean, label: string): void {
  if (!cond) throw new Error(label);
}

export function run(): void {
  let failed = 0;
  for (const [name, fn] of registered) {
    try {
      fn();
      console.log(`ok   - ${name}`);
    } catch (e) {
      failed++;
      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  for (const c of cleanups) {
    try {
      c();
    } catch {
      /* ignore */
    }
  }
  console.log(failed === 0 ? "all passed" : `${failed} failed`);
  process.exitCode = failed === 0 ? 0 : 1;
}
import { AppConfig } from "../config";
import { validateAutopay } from "../domain/autopay";
import { validateMember } from "../domain/member";
import { normalizeDevice } from "../push/deviceToken";
import { PushqClient } from "../push/pushqClient";
import { ReminderReportBuilder } from "../report/reminderReport";
import { AutopayRepository } from "../repository/autopayRepository";
import { MemberRepository } from "../repository/memberRepository";
import { ReminderService } from "../service/reminderService";
import { isLocalDateTime } from "../time/localTime";
import { notFound, ok, Router } from "./router";

const DATE = /^\d{4}-\d{2}-\d{2}$/;

export function mountAccountRoutes(router: Router, config: AppConfig, members: MemberRepository, autopays: AutopayRepository): void {
  router.add("POST", "/members", (_p, body) => {
    const m = validateMember(body, config.allowedLeads);
    return ok(members.save({ ...m, device: normalizeDevice(m.device) }));
  });

  router.add("POST", "/autopays", (_p, body) => {
    const input = validateAutopay(body);
    if (!members.find(input.memberId)) return notFound(`member ${input.memberId}`);
    return ok(autopays.create(input));
  });
}

export function mountReminderRoutes(
  router: Router,
  service: ReminderService,
  report: ReminderReportBuilder,
  members: MemberRepository,
  push: PushqClient,
): void {
  router.add("POST", "/reminders/plan", (_p, body) => {
    const date = (body as { date?: unknown } | undefined)?.date;
    if (typeof date !== "string" || !DATE.test(date)) throw new Error("date must be YYYY-MM-DD");
    return ok(service.planDay(date));
  });

  router.add("POST", "/autopays/:id/failures", (p, body) => ok(service.recordFailure(p.id, body)));

  router.add("POST", "/autopays/:id/cancel", (p) => ok(service.cancelAutopay(p.id)));

  router.add("POST", "/clock", (_p, body) => {
    const until = (body as { until?: unknown } | undefined)?.until;
    if (!isLocalDateTime(until)) throw new Error("until must be YYYY-MM-DDTHH:MM:SS");
    return ok(service.advance(until));
  });

  router.add("GET", "/reports/reminders/:date", (p) => {
    if (!DATE.test(p.date)) throw new Error("date must be YYYY-MM-DD");
    return ok(report.build(p.date, service.now()));
  });

  router.add("GET", "/members/:id/notifications", (p) => {
    const m = members.find(p.id);
    if (!m) return notFound(`member ${p.id}`);
    const notifications = push.delivered(m.device).map((d) => ({ at: d.at, tag: d.tag, message: d.message }));
    return ok({ memberId: m.id, notifications });
  });
}
import { isLocalDateTime, LocalDateTime } from "../time/localTime";

/** 자동이체(정기 출금) 계약 — 가맹점이 정한 날·시각에 출금된다. */
export interface Autopay {
  id: string;
  memberId: string;
  merchant: string;
  amount: number;
  /** 매월 출금일(1~28) */
  billingDay: number;
  /** 가맹점 출금 배치 시각 "HH:MM" */
  billingTime: string;
  active: boolean;
}

/** 출금 실패 기록 — 재출금은 실패 처리 시각 기준으로 잡힌다. */
export interface BillingFailure {
  autopayId: string;
  failedAt: LocalDateTime;
  reason: string;
}

export function validateAutopay(input: unknown): Omit<Autopay, "id" | "active"> {
  const b = (input ?? {}) as Record<string, unknown>;
  if (typeof b.memberId !== "string") throw new Error("memberId required");
  if (typeof b.merchant !== "string" || b.merchant.trim() === "") throw new Error("merchant required");
  if (typeof b.amount !== "number" || !Number.isInteger(b.amount) || b.amount <= 0) throw new Error("amount must be a positive integer (KRW)");
  if (typeof b.billingDay !== "number" || !Number.isInteger(b.billingDay) || b.billingDay < 1 || b.billingDay > 28) {
    throw new Error("billingDay must be 1..28");
  }
  if (typeof b.billingTime !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(b.billingTime)) throw new Error("billingTime must be HH:MM");
  return { memberId: b.memberId, merchant: b.merchant.trim(), amount: b.amount, billingDay: b.billingDay, billingTime: b.billingTime };
}

export function validateFailure(autopayId: string, input: unknown): BillingFailure {
  const b = (input ?? {}) as Record<string, unknown>;
  if (!isLocalDateTime(b.failedAt)) throw new Error("failedAt must be YYYY-MM-DDTHH:MM:SS");
  const reason = typeof b.reason === "string" && b.reason !== "" ? b.reason : "INSUFFICIENT_BALANCE";
  return { autopayId, failedAt: b.failedAt, reason };
}
# 출금 실패 통보 수신 (운영 메모)

출금 실패는 펌뱅킹 중계사(뱅크허브)가 출금 시스템(billing-core)과 이 서비스에 각각 통보한다.
이 서비스는 `POST /autopays/:id/failures`로 받는다.

## 통보 형식
| 필드 | 내용 |
|---|---|
| autopayId | 계약 번호 |
| failedAt | 통보 시각(KST, 초 단위) |
| reason | `INSUFFICIENT_BALANCE`·`ACCOUNT_CLOSED`·`LIMIT_EXCEEDED` |

- 통보에는 별도 거래 번호가 없다. 계약 번호와 시각으로만 구분된다.
- 뱅크허브는 수신 응답이 30초 안에 오지 않으면 같은 건을 다시 통보한다(3~6분 간격, 최대 3회). 다시 보낸 통보의 failedAt은 원래 실패 시각이 아니라 다시 보낸 시각이다.
- 08:00 출금 배치 직후처럼 통보가 몰리는 시간대에는 응답 지연으로 재통보가 자주 생긴다.

## 재출금
- billing-core가 실패 통보 기준 2시간 뒤 재출금을 잡는다. 재출금이 또 실패하면 그 시점에서 다시 2시간 뒤.
- billing-core는 재출금이 잡혀 있는 동안 들어온 통보로는 재출금을 새로 잡지 않는다.

## 장애 시
- 뱅크허브 연결이 끊기면 실패 통보가 늦게 몰려 들어온다. 재출금 안내가 재출금 뒤에 도착할 수 있으니 결제운영팀에 공유한다.
- 통보 누락 의심 시 billing-core의 실패 목록과 대조한다(운영 콘솔 > 출금 > 실패).

